export const getDownloadInvoiceUrl = (invoiceId: string,
    params?: DownloadInvoiceParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/me/invoices/${invoiceId}/download?${stringifiedParams}` : `/api/me/invoices/${invoiceId}/download`
}

